```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// Calcula el promedio de una columna numérica de un CSV.
/// - `columna`: índice 0-based de la columna.
/// - `saltar_cabecera`: si es `true`, ignora el primer registro.
///
/// Devuelve `Ok(None)` si no encontró valores numéricos.
pub fn promedio_columna_csv<P: AsRef<Path>>(
    ruta: P,
    columna: usize,
    saltar_cabecera: bool,
) -> io::Result<Option<f64>> {
    let archivo = File::open(ruta)?;
    let mut lector = BufReader::with_capacity(64 * 1024, archivo);
    let mut buffer = [0u8; 64 * 1024];

    let mut suma = 0.0_f64;
    let mut cantidad = 0_u64;

    let mut campo = Vec::<u8>::new();
    let mut col_actual = 0_usize;
    let mut en_comillas = false;
    let mut comilla_pendiente = false;
    let mut registro = 0_u64;
    let mut registro_iniciado = false;

    fn terminar_campo(
        campo: &mut Vec<u8>,
        col_actual: usize,
        columna: usize,
        registro: u64,
        saltar_cabecera: bool,
        suma: &mut f64,
        cantidad: &mut u64,
    ) -> io::Result<()> {
        if col_actual == columna && !(saltar_cabecera && registro == 0) {
            let s = std::str::from_utf8(campo)
                .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
            let s = s.trim();

            if !s.is_empty() {
                let valor: f64 = s.parse().map_err(|e| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        format!(
                            "valor no numérico en el registro {}, columna {}: {:?} ({})",
                            registro + 1,
                            columna + 1,
                            s,
                            e
                        ),
                    )
                })?;

                *suma += valor;
                *cantidad += 1;
            }

            campo.clear();
        }

        Ok(())
    }

    loop {
        let leidos = lector.read(&mut buffer)?;
        if leidos == 0 {
            break;
        }

        for &b in &buffer[..leidos] {
            if en_comillas {
                if comilla_pendiente {
                    if b == b'"' {
                        // "" dentro de un campo entre comillas: comilla literal.
                        if col_actual == columna {
                            campo.push(b'"');
                        }
                        comilla_pendiente = false;
                        registro_iniciado = true;
                        continue;
                    } else {
                        // La comilla anterior cerraba el campo.
                        en_comillas = false;
                        comilla_pendiente = false;
                        // Procesamos `b` como byte fuera de comillas.
                    }
                } else if b == b'"' {
                    comilla_pendiente = true;
                    registro_iniciado = true;
                    continue;
                } else {
                    if col_actual == columna {
                        campo.push(b);
                    }
                    registro_iniciado = true;
                    continue;
                }
