static int sel_edad(const Persona *p)      { return p->edad; }
static int sel_salario(const Persona *p)   { return p->salario; }
static int sel_antiguedad(const Persona *p){ return p->antiguedad; }

int leer_campo(const Persona *p, SelectorInt selector) {
