func SinNombre(u User) bool { return strings.TrimSpace(u.Name) == "" }
func SinEmail(u User) bool  { return strings.TrimSpace(u.Email) == "" }
func SinPhone(u User) bool  { return strings.TrimSpace(u.Phone) == "" }

// después
func vacio(get func(User) string) func(User) bool {
	return func(u User) bool { return strings.TrimSpace(get(u)) == "" }
