// View-projection aplicada a un column-vector. Si el juego guarda la matriz
// transpuesta (column-major), cambiá m[i][j] por m[j][i] en las cuatro filas.
inline bool worldToScreen(const Vec3& world, Vec2& out,
                          const ViewMatrix& vm, int sw, int sh) {
    const float w = vm.m[3][0]*world.x + vm.m[3][1]*world.y
                  + vm.m[3][2]*world.z + vm.m[3][3];
    if (w < 0.01f) return false;               // detrás del near plane

    const float inv = 1.0f / w;
    const float x = (vm.m[0][0]*world.x + vm.m[0][1]*world.y
                   + vm.m[0][2]*world.z + vm.m[0][3]) * inv;
    const float y = (vm.m[1][0]*world.x + vm.m[1][1]*world.y
                   + vm.m[1][2]*world.z + vm.m[1][3]) * inv;

    out.x = sw * 0.5f + x * sw * 0.5f;
    out.y = sh * 0.5f - y * sh * 0.5f;
    return true;
}
